package com.yisy.modules.doraneuron.protocol.unity;

import java.io.Serializable;

/**
 * Describes a Unity client connected to this Neuron.
 *
 * The Neuron tracks each connected Unity client for AI assistance,
 * model delivery, and experience collection from game sessions.
 */
public class UnityClientInfo implements Serializable {

    private static final long serialVersionUID = 1L;

    /** Unique client ID generated by the Unity client. */
    private String clientId;

    /** Client type identifier (e.g. "unity", "babylon"). */
    private String clientType;

    /** Player ID associated with this client session. */
    private String playerId;

    /** Session ID from the game server connection. */
    private String sessionId;

    /** Current ONNX model version on the client. */
    private long clientModelVersion;

    /** Timestamp of last heartbeat (epoch ms). */
    private long lastHeartbeat;

    /** Number of AI predictions requested by this client. */
    private int predictionCount;

    /** Number of experience samples collected from this client. */
    private int experienceCount;

    /** Whether AI assistance is enabled for this client. */
    private boolean aiAssistanceEnabled;

    /** Geographic region hint for load balancing. */
    private String region;

    public UnityClientInfo() {
        this.lastHeartbeat = System.currentTimeMillis();
        this.aiAssistanceEnabled = true;
    }

    // ── Getters and Setters ───────────────────────────────────────────────────

    public String getClientId() {
        return clientId;
    }

    public void setClientId(String clientId) {
        this.clientId = clientId;
    }

    public String getClientType() {
        return clientType;
    }

    public void setClientType(String clientType) {
        this.clientType = clientType;
    }

    public String getPlayerId() {
        return playerId;
    }

    public void setPlayerId(String playerId) {
        this.playerId = playerId;
    }

    public String getSessionId() {
        return sessionId;
    }

    public void setSessionId(String sessionId) {
        this.sessionId = sessionId;
    }

    public long getClientModelVersion() {
        return clientModelVersion;
    }

    public void setClientModelVersion(long clientModelVersion) {
        this.clientModelVersion = clientModelVersion;
    }

    public long getLastHeartbeat() {
        return lastHeartbeat;
    }

    public void setLastHeartbeat(long lastHeartbeat) {
        this.lastHeartbeat = lastHeartbeat;
    }

    public int getPredictionCount() {
        return predictionCount;
    }

    public void setPredictionCount(int predictionCount) {
        this.predictionCount = predictionCount;
    }

    public int getExperienceCount() {
        return experienceCount;
    }

    public void setExperienceCount(int experienceCount) {
        this.experienceCount = experienceCount;
    }

    public boolean isAiAssistanceEnabled() {
        return aiAssistanceEnabled;
    }

    public void setAiAssistanceEnabled(boolean aiAssistanceEnabled) {
        this.aiAssistanceEnabled = aiAssistanceEnabled;
    }

    public String getRegion() {
        return region;
    }

    public void setRegion(String region) {
        this.region = region;
    }

    @Override
    public String toString() {
        return "UnityClientInfo{clientId='" + clientId + "', playerId='" + playerId +
                "', modelVersion=" + clientModelVersion + ", predictions=" + predictionCount + '}';
    }
}
